WITH RECURSIVE n(i) AS (SELECT 0 UNION ALL SELECT i + 1 FROM n WHERE i < 6) INSERT INTO vt0(rowid, s0) SELECT 11 + i, fts5_locale('en', (json('["apple","apricot","banana","band","bandit","cherry","chess","date","delta","echo","eagle","fig","figure","grape","kiwi","lemon","running","runs","café","naïve","t1","u3","v5","zeta","relational","conditional","hesitanci","digitizer","operator","feudalism","decisiveness","hopefulness","callousness","sensitiviti","triplicate","formative","formalize","electrical","goodness","revival","allowance","inference","adjustable","replacement","adoption","activate","generalization","caresses"]') ->> (((i * 1) % 48 + 48) % 48)) || ' t' || (i % 7) || ' ' || (json('["apple","apricot","banana","band","bandit","cherry","chess","date","delta","echo","eagle","fig","figure","grape","kiwi","lemon","running","runs","café","naïve","t1","u3","v5","zeta","relational","conditional","hesitanci","digitizer","operator","feudalism","decisiveness","hopefulness","callousness","sensitiviti","triplicate","formative","formalize","electrical","goodness","revival","allowance","inference","adjustable","replacement","adoption","activate","generalization","caresses"]') ->> (((i + 3) % 48 + 48) % 48)) || ' ' || (json('["valenci","conformabli","radicalli","differentli","vileli","analogousli","vietnamization","predication","formaliti","sensibiliti","archeologi","electriciti","hopeful","airliner","gyroscopic","defensible","irritant","adjustment","dependent","homologou","communism","angulariti","homologous","effective","bowdlerize","ponies","caress","cats","agreed","feed","plastered","motoring","sing","happy","conflated","troubled","sized","hopping","falling","filing","probate","rate","controll","roll","tanned","sky","ration","ment"]') ->> (((i * 1 + 0) % 48 + 48) % 48))) FROM n;
